<template><view class="page"><view class="cube">3D</view><text class="title">{{ title }}</text><text class="description">小程序端 3D 原生预览将在下一阶段接入。当前可通过已配置的 H5 模型预览页打开模型。</text><button class="open" @tap="openH5">打开 3D 预览</button><text class="hint">需要在 .env 中配置 VITE_MODEL_PREVIEW_BASE_URL，并将该 HTTPS 域名添加至微信小程序业务域名。</text></view></template>
<script setup lang="ts">import { ref } from 'vue';import { onLoad } from '@dcloudio/uni-app';const id=ref(''),title=ref('3D 模型');onLoad((q:any)=>{id.value=q.id||'';title.value=decodeURIComponent(q.title||'3D 模型')});function openH5(){const base=(import.meta.env.VITE_MODEL_PREVIEW_BASE_URL||'').replace(/\/$/,'');if(!base)return uni.showToast({title:'尚未配置 H5 预览域名',icon:'none'});uni.setClipboardData({data:`${base}?assetId=${id.value}`,success:()=>uni.showToast({title:'预览链接已复制',icon:'none'})})}</script>
<style scoped lang="scss">.page{min-height:100vh;padding:130rpx 58rpx;text-align:center}.cube{width:210rpx;height:210rpx;margin:0 auto 48rpx;border-radius:32rpx;background:linear-gradient(145deg,#3a1d15,#b75632);color:#fff;display:flex;align-items:center;justify-content:center;font-size:56rpx;font-weight:800;box-shadow:26rpx 26rpx 0 #f0c5a6}.title{font-size:42rpx;font-weight:800;display:block}.description{display:block;color:#866c60;line-height:1.8;font-size:27rpx;margin:26rpx 0}.open{height:94rpx;line-height:94rpx;border-radius:48rpx;background:#953d24;color:#fff;font-size:29rpx}.hint{display:block;margin-top:26rpx;color:#ad9589;font-size:21rpx;line-height:1.6}</style>
